import { Injectable, signal, computed, inject, Injector } from '@angular/core';
import { CustomService } from '@clinicaloffice/mpage-developer';

/**
 * File information for validation
 */
export interface FileInfo {
  filename: string;
  filesize: number;
  filedate: string;
  filetype: string;
  /** Local file content (populated when file is loaded) */
  content?: string;
}

/**
 * CCL response structure for file listing
 */
interface CclFileListResponse {
  statusData: { status: string };
  files?: Array<{
    filename: string;
    filesize: number;
    filedate: string;
    filetype: string;
  }>;
  error?: string;
}

/**
 * CCL response structure for file reading
 */
interface CclFileReadResponse {
  statusData: { status: string };
  content?: string;
  error?: string;
}

/**
 * Service for browsing and loading blood bank extract files.
 * Supports both online mode (CCL in Cerner) and offline mode (local files).
 * Provides reactive state management using Angular signals.
 */
@Injectable({
  providedIn: 'root'
})
export class FileBrowserService {
  private injector = inject(Injector);
  private _customService: CustomService | null = null;

  /** Lazy getter for CustomService - only injected when needed in online mode */
  private get customService(): CustomService {
    if (!this._customService) {
      this._customService = this.injector.get(CustomService);
    }
    return this._customService;
  }

  // Reactive state using signals
  private _files = signal<FileInfo[]>([]);
  private _loading = signal(false);
  private _error = signal<string | null>(null);
  private _directory = signal('cclscratch:');
  private _offlineMode = signal(true);

  // Public readonly accessors
  readonly files = this._files.asReadonly();
  readonly loading = this._loading.asReadonly();
  readonly error = this._error.asReadonly();
  readonly directory = this._directory.asReadonly();
  readonly offlineMode = this._offlineMode.asReadonly();

  // Computed values
  readonly fileCount = computed(() => this._files().length);
  readonly hasFiles = computed(() => this._files().length > 0);
  readonly hasError = computed(() => this._error() !== null);

  /**
   * Enable online mode for CCL-based file operations
   * Used when running in Cerner MPage context
   */
  enableOnlineMode(): void {
    this._offlineMode.set(false);
    this._directory.set('cclscratch:');
    this._error.set(null);
  }

  /**
   * Enable offline mode for local file browsing
   * Used when running outside Cerner (GitHub Pages, local dev)
   */
  enableOfflineMode(): void {
    this._offlineMode.set(true);
    this._directory.set('Local Files');
    this._error.set(null);
  }

  /**
   * List files in directory via CCL (online mode) or return empty (offline mode)
   * @param directory - Directory path for CCL listing (default: cclscratch:)
   */
  listFiles(directory: string = 'cclscratch:'): void {
    if (this._offlineMode()) {
      // In offline mode, do nothing - user picks local files
      return;
    }

    this._loading.set(true);
    this._error.set(null);
    this._directory.set(directory);

    this.customService.load(
      {
        customScript: {
          script: [{
            name: 'mrha_bb_val_list_dir:group1',
            run: 'pre',
            id: 'listDir',
            parameters: {
              directory: directory
            }
          }],
          clearPatientSource: true
        }
      },
      [],
      () => {
        const response = this.customService.get('listDir') as CclFileListResponse;

        // Use explicit null checks for older browser compatibility (no ?. operator)
        const isSuccess = response && response.statusData &&
                          response.statusData.status === 'S' && response.files;

        if (isSuccess) {
          // Non-null assertion safe here - we checked response.files exists in isSuccess
          this._files.set(response.files!.map(f => ({
            filename: f.filename,
            filesize: f.filesize,
            filedate: f.filedate,
            filetype: f.filetype || this.deriveFileType(f.filename)
          })));
          this._error.set(null);
        } else {
          const errorMsg = (response && response.error) ? response.error : 'Failed to list directory';
          this._error.set(errorMsg);
          this._files.set([]);
        }

        this._loading.set(false);
      }
    );
  }

  /**
   * Read file content via CCL (online mode) or return local content (offline mode)
   * @param directory - Directory path for CCL read
   * @param filename - Name of file to read
   * @param callback - Callback with content or error
   */
  readFile(
    directory: string,
    filename: string,
    callback: (content: string | null, error: string | null) => void
  ): void {
    // In offline mode, check if we have the content already loaded
    if (this._offlineMode()) {
      const file = this._files().find(f => f.filename === filename);
      // Use explicit null check for older browser compatibility (no ?. operator)
      if (file && file.content) {
        callback(file.content, null);
      } else {
        callback(null, 'File content not available - use local file picker');
      }
      return;
    }

    // Online mode - read via CCL
    this.customService.load(
      {
        customScript: {
          script: [{
            name: 'mrha_bb_val_read_file:group1',
            run: 'pre',
            id: 'readFile',
            parameters: {
              directory: directory,
              filename: filename
            }
          }],
          clearPatientSource: true
        }
      },
      [],
      () => {
        const response = this.customService.get('readFile') as CclFileReadResponse;

        // Use explicit null checks for older browser compatibility (no ?. operator)
        const isSuccess = response && response.statusData &&
                          response.statusData.status === 'S' && response.content !== undefined;

        if (isSuccess) {
          // Non-null assertion safe here - we checked response.content !== undefined in isSuccess
          callback(response.content!, null);
        } else {
          const errorMsg = (response && response.error) ? response.error : 'Failed to read file: ' + filename;
          callback(null, errorMsg);
        }
      }
    );
  }

  /**
   * Clear the current files list and error state
   */
  clearFiles(): void {
    this._files.set([]);
    this._error.set(null);
  }

  /**
   * Derive file type from filename pattern (same logic as CCL script)
   */
  deriveFileType(filename: string): string {
    const lowerName = filename.toLowerCase();
    if (/^ptnt_instr.*\.txt$/i.test(lowerName)) return 'PTNT_INSTR';
    if (/^ptnt_cmt.*\.txt$/i.test(lowerName)) return 'PTNT_CMT';
    if (/^ptnt_(?!cmt|instr).*\.txt$/i.test(lowerName)) return 'PTNT';
    if (/^unit_cmt.*\.txt$/i.test(lowerName)) return 'UNIT_CMT';
    if (/^unit_(?!cmt).*\.txt$/i.test(lowerName)) return 'UNIT';
    if (/^spec_attr.*\.txt$/i.test(lowerName)) return 'SPEC_ATTR';
    return 'OTHER';
  }

  /**
   * Add files from local file picker (offline mode)
   * @param fileList - FileList from HTML file input
   */
  async addLocalFiles(fileList: FileList): Promise<void> {
    this._loading.set(true);
    this._error.set(null);

    const newFiles: FileInfo[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const file = fileList[i];

      // Only accept .txt files
      if (!file.name.toLowerCase().endsWith('.txt')) {
        continue;
      }

      try {
        const content = await this.readLocalFile(file);
        newFiles.push({
          filename: file.name,
          filesize: file.size,
          filedate: file.lastModified
            ? new Date(file.lastModified).toISOString()
            : '',
          filetype: this.deriveFileType(file.name),
          content: content
        });
      } catch {
        // Skip files that can't be read - error logged silently
      }
    }

    // Merge with existing files (avoid duplicates)
    const existingNames = new Set(this._files().map(f => f.filename));
    const uniqueNewFiles = newFiles.filter(f => !existingNames.has(f.filename));

    this._files.update(files => [...files, ...uniqueNewFiles]);
    this._loading.set(false);
  }

  /**
   * Read a local file using FileReader API
   */
  private readLocalFile(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = () => reject(reader.error);
      reader.readAsText(file);
    });
  }

  /**
   * Get file content (for offline mode, content is already loaded)
   * @param filename - Name of file to get content for
   */
  getLocalFileContent(filename: string): string | null {
    const file = this._files().find(f => f.filename === filename);
    // Use explicit null check for older browser compatibility (no ?. operator)
    return (file && file.content) ? file.content : null;
  }

  /**
   * Remove a file from the list (offline mode only)
   */
  removeFile(filename: string): void {
    this._files.update(files => files.filter(f => f.filename !== filename));
  }
}
