import { Component, Input, ChangeDetectionStrategy, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  FileType,
  FileResult,
  ValidationStatus,
  Issue,
  IssueSeverity
} from '../../models/validation.model';

/**
 * File Detail Component
 *
 * Collapsible component showing per-file validation details:
 * - Expandable header with status, file name, record count
 * - Stats cards (Records, Fields, Completion %, Critical Issues)
 * - Issues list with severity styling
 *
 * Matches standalone validator.html file-by-file analysis section
 */
@Component({
  selector: 'app-file-detail',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './file-detail.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FileDetailComponent {

  /** File type being displayed */
  @Input() fileType: FileType = 'PTNT';

  /** Validation result for this file */
  @Input() fileResult: FileResult | null = null;

  /** Original filename */
  @Input() filename: string = '';

  /** Expanded state (using signal for reactivity) */
  expanded = signal(false);

  /**
   * Toggle expanded state
   */
  toggleExpanded(): void {
    this.expanded.update(v => !v);
  }

  /**
   * Get CSS class for status badge
   */
  getStatusBadgeClass(status: ValidationStatus): string {
    switch (status) {
      case 'PASS': return 'status-pass';
      case 'WARN': return 'status-warn';
      case 'FAIL': return 'status-fail';
      default: return '';
    }
  }

  /**
   * Get CSS class for issue severity
   */
  getIssueSeverityClass(severity: IssueSeverity): string {
    switch (severity) {
      case 'critical': return 'issue-critical';
      case 'warning': return 'issue-warning';
      default: return '';
    }
  }

  /**
   * Format number with locale-specific separators
   */
  formatNumber(value: number): string {
    return value.toLocaleString();
  }

  /**
   * Get record count
   */
  get recordCount(): number {
    return this.fileResult?.recordCount ?? 0;
  }

  /**
   * Get field count display (actual/expected)
   */
  get fieldCountDisplay(): string {
    if (!this.fileResult) return '0/0';
    return `${this.fileResult.fieldCount}/${this.fileResult.expectedFields}`;
  }

  /**
   * Get completion rate percentage
   */
  get completionRate(): number {
    return this.fileResult?.completionRate ?? 0;
  }

  /**
   * Get critical issues count
   */
  get criticalIssuesCount(): number {
    return this.fileResult?.issues.filter(i => i.severity === 'critical').length ?? 0;
  }

  /**
   * Get issues list
   */
  get issues(): Issue[] {
    return this.fileResult?.issues ?? [];
  }

  /**
   * Get file status
   */
  get status(): ValidationStatus {
    return this.fileResult?.status ?? 'PASS';
  }

  /**
   * Check if there are any issues
   */
  get hasIssues(): boolean {
    return this.issues.length > 0;
  }

  /**
   * Format issue samples for display
   */
  formatSamples(issue: Issue): string {
    if (!issue.samples || issue.samples.length === 0) return '';

    return issue.samples.slice(0, 3).map(s => {
      if (s.line) {
        if (s.value !== undefined) {
          return `Line ${s.line}: "${s.value}"`;
        } else if (s.actual !== undefined) {
          return `Line ${s.line}: ${s.actual} fields`;
        }
        return `Line ${s.line}`;
      }
      return JSON.stringify(s);
    }).join(', ');
  }
}
