import { Component, Input, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FileIssue, CrossFileResult } from '../../models/validation.model';

/**
 * Critical Issues Component
 *
 * Displays banner of critical issues that must be fixed:
 * - Red background styling for urgency
 * - List of critical issues with file source
 * - Hidden when no critical issues exist
 *
 * Matches standalone validator.html Critical Issues section
 */
@Component({
  selector: 'app-critical-issues',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './critical-issues.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CriticalIssuesComponent {

  /** Critical issues from file validation */
  @Input() criticalIssues: FileIssue[] = [];

  /** Cross-file validation results with errors */
  @Input() crossFileErrors: CrossFileResult[] = [];

  /**
   * Check if there are any critical issues to display
   */
  get hasIssues(): boolean {
    return this.criticalIssues.length > 0 || this.crossFileErrors.length > 0;
  }

  /**
   * Get combined count of all critical issues
   */
  get totalCount(): number {
    return this.criticalIssues.length + this.crossFileErrors.length;
  }

  /**
   * Format count for display
   */
  formatCount(count: number): string {
    return count.toLocaleString();
  }

  /**
   * Get file source display for issue
   */
  getFileSource(issue: FileIssue): string {
    return issue.file || 'Unknown';
  }

  /**
   * Get cross-file error message
   */
  getCrossFileMessage(result: CrossFileResult): string {
    return result.rule;
  }

  /**
   * Get orphan count from cross-file result
   */
  getOrphanCount(result: CrossFileResult): number {
    return result.orphans;
  }
}
