import { Component, Input, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  ValidationResults,
  ValidationStatus,
  FileType,
  FileResult
} from '../../models/validation.model';

/**
 * Results Summary Component
 *
 * Displays executive summary of validation results:
 * - Overall status badge (PASS/WARN/FAIL)
 * - Total records, critical issues, warnings counts
 * - File summary table with per-file stats
 *
 * Matches standalone validator.html Executive Summary section
 */
@Component({
  selector: 'app-results-summary',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './results-summary.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ResultsSummaryComponent {

  /** Validation results to display */
  @Input() results: ValidationResults | null = null;

  /**
   * Get CSS classes for status badge
   */
  getStatusBadgeClass(status: ValidationStatus): string {
    switch (status) {
      case 'PASS': return 'status-pass';
      case 'WARN': return 'status-warn';
      case 'FAIL': return 'status-fail';
      default: return '';
    }
  }

  /**
   * Format number with locale-specific separators
   */
  formatNumber(value: number): string {
    return value.toLocaleString();
  }

  /**
   * Get timestamp as formatted string
   */
  getTimestamp(): string {
    return this.results?.timestamp?.toLocaleString() ?? '';
  }

  /**
   * Get file types as array for iteration
   */
  getFileTypes(): FileType[] {
    if (!this.results) return [];
    return Array.from(this.results.files.keys());
  }

  /**
   * Get file result for a type
   */
  getFileResult(type: FileType): FileResult | undefined {
    return this.results?.files.get(type);
  }

  /**
   * Get total records count
   */
  get totalRecords(): number {
    return this.results?.totalRecords ?? 0;
  }

  /**
   * Get critical issues count
   */
  get criticalCount(): number {
    return this.results?.criticalIssues.length ?? 0;
  }

  /**
   * Get warnings count
   */
  get warningCount(): number {
    return this.results?.warnings.length ?? 0;
  }

  /**
   * Get overall status
   */
  get overallStatus(): ValidationStatus {
    return this.results?.overallStatus ?? 'PASS';
  }
}
