import {
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  OnInit,
  output,
  signal
} from '@angular/core';
import { FileBrowserService, FileInfo } from '../../services/file-browser.service';

/**
 * Check if running in Cerner MPage context
 * Cerner provides DiscernObjectFactory for COM interop
 * Note: Avoid optional chaining (?.) for older browser compatibility
 */
function isCernerEnvironment(): boolean {
  try {
    // Check for Cerner's DiscernObjectFactory (available in PowerChart)
    // Using explicit null checks instead of ?. for older browser support
    const win = window as any;
    const ext = win.external;
    if (ext && typeof ext.DiscernObjectFactory !== 'undefined') {
      return true;
    }
    return false;
  } catch {
    return false;
  }
}

/**
 * Extended file info with selection state
 */
interface SelectableFile extends FileInfo {
  selected: boolean;
}

/**
 * File browser component for displaying and selecting blood bank extract files.
 * Calls CCL script mrha_bb_val_list_dir on initialization and provides
 * file selection for validation.
 */
@Component({
  selector: 'app-file-browser',
  standalone: true,
  imports: [],
  templateUrl: './file-browser.component.html',
  styleUrls: ['./file-browser.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class FileBrowserComponent implements OnInit {
  private fileBrowserService = inject(FileBrowserService);

  /** Flag to track if we're in Cerner environment - checked once at startup */
  private readonly inCernerEnvironment = isCernerEnvironment();

  // Output events for parent components
  validateFiles = output<FileInfo[]>();

  // Internal state for file selection
  private _selectableFiles = signal<SelectableFile[]>([]);

  // Public readonly state (signals)
  readonly loading = this.fileBrowserService.loading;
  readonly error = this.fileBrowserService.error;
  readonly directory = this.fileBrowserService.directory;
  readonly offlineMode = this.fileBrowserService.offlineMode;
  readonly selectableFiles = this._selectableFiles.asReadonly();

  // Plain property getters for template (avoids signal() calls in older browsers)
  // These are read by Angular's change detection without calling signal functions
  get inCerner(): boolean { return this.inCernerEnvironment; }
  get isOfflineMode(): boolean { return this.fileBrowserService.offlineMode(); }
  get isLoading(): boolean { return this.fileBrowserService.loading(); }
  get directoryPath(): string { return this.fileBrowserService.directory(); }
  get errorMessage(): string | null { return this.fileBrowserService.error(); }
  get files(): SelectableFile[] { return this._selectableFiles(); }
  get totalFileCount(): number { return this._selectableFiles().length; }
  get totalSelectedCount(): number { return this._selectableFiles().filter(f => f.selected).length; }
  get hasAnySelectedFiles(): boolean { return this.totalSelectedCount > 0; }
  get areAllSelected(): boolean { return this.totalFileCount > 0 && this._selectableFiles().every(f => f.selected); }
  get areNoneSelected(): boolean { return this._selectableFiles().every(f => !f.selected); }

  // Computed values (keep for compatibility)
  readonly fileCount = computed(() => this._selectableFiles().length);
  readonly selectedCount = computed(() =>
    this._selectableFiles().filter(f => f.selected).length
  );
  readonly hasSelectedFiles = computed(() => this.selectedCount() > 0);
  readonly allSelected = computed(() =>
    this._selectableFiles().length > 0 &&
    this._selectableFiles().every(f => f.selected)
  );
  readonly noneSelected = computed(() =>
    this._selectableFiles().every(f => !f.selected)
  );

  ngOnInit(): void {
    this.loadFiles();
  }

  /**
   * Load files - detect Cerner environment and use appropriate mode
   */
  loadFiles(): void {
    // Check if running in Cerner MPage context BEFORE trying to inject services
    if (this.inCernerEnvironment) {
      // Online mode - CCL available
      this.fileBrowserService.enableOnlineMode();
      this.fileBrowserService.listFiles('cclscratch:');
      // Watch for CCL errors and fallback to offline if needed
      this.watchForCclError();
    } else {
      // Offline mode - local file browsing (outside Cerner)
      this.enableOfflineMode();
    }

    // Subscribe to file changes using effect-like pattern
    this.syncFilesFromService();
  }

  /**
   * Watch for CCL errors and switch to offline mode if CCL fails
   */
  private watchForCclError(): void {
    const checkInterval = setInterval(() => {
      if (!this.fileBrowserService.loading()) {
        clearInterval(checkInterval);
        // If there's an error after loading completes, switch to offline mode
        if (this.fileBrowserService.error()) {
          this.enableOfflineMode();
        }
      }
    }, 100);
    // Timeout after 2 seconds (reduced from 5s for faster fallback)
    setTimeout(() => {
      clearInterval(checkInterval);
      // If still loading after 2 seconds, assume CCL not available
      if (this.fileBrowserService.loading()) {
        this.enableOfflineMode();
      }
    }, 2000);
  }

  /**
   * Manually switch to offline mode (for user button click)
   */
  switchToOfflineMode(): void {
    this.enableOfflineMode();
  }

  /**
   * Enable offline mode for local file browsing
   */
  enableOfflineMode(): void {
    this.fileBrowserService.enableOfflineMode();
  }

  /**
   * Refresh the file list
   */
  refresh(): void {
    this._selectableFiles.set([]);
    this.loadFiles();
  }

  /**
   * Sync files from service to local selectable files state
   */
  private syncFilesFromService(): void {
    // Create a computed effect that updates when service files change
    const checkInterval = setInterval(() => {
      const serviceFiles = this.fileBrowserService.files();
      const currentFiles = this._selectableFiles();

      // Only update if service has files and they differ from current
      if (serviceFiles.length > 0 &&
          (currentFiles.length === 0 ||
           serviceFiles.length !== currentFiles.length)) {
        this._selectableFiles.set(
          serviceFiles.map(file => ({
            ...file,
            selected: false
          }))
        );
        clearInterval(checkInterval);
      }

      // Also stop if we've stopped loading
      if (!this.fileBrowserService.loading() && serviceFiles.length === 0) {
        clearInterval(checkInterval);
      }
    }, 100);

    // Cleanup after 10 seconds max
    setTimeout(() => clearInterval(checkInterval), 10000);
  }

  /**
   * Toggle selection for a specific file
   */
  toggleFileSelection(index: number): void {
    this._selectableFiles.update(files => {
      const updated = [...files];
      if (updated[index]) {
        updated[index] = {
          ...updated[index],
          selected: !updated[index].selected
        };
      }
      return updated;
    });
  }

  /**
   * Select all files
   */
  selectAll(): void {
    this._selectableFiles.update(files =>
      files.map(file => ({ ...file, selected: true }))
    );
  }

  /**
   * Deselect all files
   */
  deselectAll(): void {
    this._selectableFiles.update(files =>
      files.map(file => ({ ...file, selected: false }))
    );
  }

  /**
   * Emit selected files for validation
   */
  onValidateSelected(): void {
    const selected = this._selectableFiles()
      .filter(f => f.selected)
      .map(({ selected, ...file }) => file as FileInfo);

    if (selected.length > 0) {
      this.validateFiles.emit(selected);
    }
  }

  /**
   * Format file size for display
   */
  formatFileSize(bytes: number): string {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  }

  /**
   * Get CSS class for file type badge
   */
  getFileTypeBadgeClass(filetype: string): string {
    const typeClasses: Record<string, string> = {
      'PTNT': 'badge-patient',
      'PTNT_CMT': 'badge-patient-comment',
      'PTNT_INSTR': 'badge-patient-instruction',
      'UNIT': 'badge-unit',
      'UNIT_CMT': 'badge-unit-comment',
      'SPEC_ATTR': 'badge-spec-attr',
      'OTHER': 'badge-other'
    };
    return typeClasses[filetype] || 'badge-other';
  }

  /**
   * Track by function for ngFor performance
   */
  trackByFilename(index: number, file: SelectableFile): string {
    return file.filename;
  }

  /**
   * Handle local file selection (offline mode)
   */
  async onLocalFilesSelected(event: Event): Promise<void> {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files.length > 0) {
      await this.fileBrowserService.addLocalFiles(input.files);
      // Sync the new files to selectable list
      this.syncFilesFromService();
      // Reset the input so the same files can be selected again
      input.value = '';
    }
  }

  /**
   * Remove a file from the list (offline mode only)
   */
  removeFile(filename: string, event: Event): void {
    event.stopPropagation();
    this.fileBrowserService.removeFile(filename);
    this._selectableFiles.update(files =>
      files.filter(f => f.filename !== filename)
    );
  }
}
